{
    /** @return array<string, mixed> */
    public function integrationCapabilities(): array
    {
        return ['auth' => ['strategy' => 'pat_or_bearer', 'legacy_auth_type' => 'api_key', 'credential_mode' => 'secret', 'setup_flows' => ['manual_secret', 'manual_token'], 'requires_browser_for_setup' => false, 'refreshable' => false, 'token_keys' => ['personal_access_token', 'access_token'], 'notes' => ['Azure DevOps supports PAT Basic auth and Microsoft Entra bearer tokens. PATs are sent as Basic auth with an empty username.']], 'host_availability' => ['web' => ['setup_supported' => true, 'runtime_supported' => true, 'setup_mode' => 'manual_secret'], 'cli' => ['setup_supported' => true, 'runtime_supported' => true, 'setup_mode' => 'manual_secret', 'runtime_mode' => 'normal']], 'runtime_requirements' => [], 'compatibility' => ['web_setup_supported' => true, 'web_runtime_supported' => true, 'cli_setup_supported' => true, 'cli_runtime_supported' => true]];
    }

    public function appName(): string { return 'azure-devops'; }
    public function appMeta(): array { return ['label' => 'Azure DevOps', 'description' => 'Azure DevOps projects, repos, pipelines, builds, releases, work items, artifacts, tests, security, and service hooks', 'icon' => 'ph:microsoft-logo', 'logo' => 'simple-icons:azuredevops']; }
    public function integrationMeta(): array { return ['name' => 'Azure DevOps', 'description' => 'Manage Azure DevOps Services APIs for projects, repositories, pull requests, builds, releases, pipelines, work items, artifacts, tests, security, service hooks, and organization resources.', 'icon' => 'ph:microsoft-logo', 'logo' => 'simple-icons:azuredevops', 'category' => 'productivity', 'badge' => 'verified', 'docs_url' => 'https://learn.microsoft.com/en-us/rest/api/azure/devops/?view=azure-devops-rest-7.2']; }
    public function configSchema(): array { return [['key' => 'personal_access_token', 'type' => 'secret', 'label' => 'Personal Access Token', 'placeholder' => 'Azure DevOps PAT', 'hint' => 'Optional when using a Microsoft Entra access token.', 'required' => false], ['key' => 'access_token', 'type' => 'secret', 'label' => 'Access Token', 'placeholder' => 'Microsoft Entra bearer token', 'required' => false], ['key' => 'organization', 'type' => 'text', 'label' => 'Organization', 'placeholder' => 'contoso', 'hint' => 'Used only by the connection test.', 'required' => false], ['key' => 'base_url', 'type' => 'url', 'label' => 'Base URL Override', 'placeholder' => 'https://dev.azure.com/contoso', 'hint' => 'Optional for Azure DevOps Server, proxies, or tests. Endpoint paths still include their official path placeholders.', 'required' => false]]; }

    /** @param  array<string, mixed>  $config  Credential and endpoint settings. @return array{success: bool, message?: string, error?: string} */
    public function testConnection(array $config): array
    {
        $pat = (string) ($config['personal_access_token'] ?? '');
        $accessToken = (string) ($config['access_token'] ?? '');
        $organization = trim((string) ($config['organization'] ?? ''));
        $baseUrl = rtrim((string) ($config['base_url'] ?? ''), '/');
        if ($pat === '' && $accessToken === '') { return ['success' => false, 'error' => 'Provide an Azure DevOps PAT or access token.']; }
        if ($baseUrl === '' && $organization === '') { return ['success' => false, 'error' => 'Provide an Azure DevOps organization or base URL for the connection test.']; }

        try {
            $headers = ['Accept' => 'application/json'];
            if ($pat !== '') { $headers['Authorization'] = 'Basic ' . base64_encode(':' . $pat); } else { $headers['Authorization'] = 'Bearer ' . $accessToken; }
            $url = ($baseUrl !== '' ? $baseUrl : 'https://dev.azure.com/' . rawurlencode($organization)) . '/_apis/projects';
            $response = Http::withHeaders($headers)->timeout(10)->get($url, ['api-version' => '7.2']);
            if (!$response->successful()) { return ['success' => false, 'error' => 'Azure DevOps returned HTTP ' . $response->status() . '.']; }
            return ['success' => true, 'message' => 'Connected to Azure DevOps.'];
        } catch (\Throwable $e) {
            return ['success' => false, 'error' => $e->getMessage()];
        }
    }

    public function validationRules(): array { return ['personal_access_token' => 'nullable|string', 'access_token' => 'nullable|string', 'organization' => 'nullable|string', 'base_url' => 'nullable|url']; }
