    /** @param  array<string, mixed>  $context  Runtime account context. */
    public function createTool(string $class, array $context = []): Tool { return new $class($this->resolveService($context)); }

    /** @param  array<string, mixed>  $context  Runtime account context. */
    private function resolveService(array $context = []): AzureDevOpsService
    {
        $account = $context['account'] ?? null;
        if ($account !== null) {
            $creds = app(CredentialResolver::class);
            return new AzureDevOpsService(personalAccessToken: $creds->get('azure-devops', 'personal_access_token', '', $account), accessToken: $creds->get('azure-devops', 'access_token', '', $account), baseUrl: $creds->get('azure-devops', 'base_url', '', $account));
        }

        return app(AzureDevOpsService::class);
    }

    public function scriptDocsPath(): ?string { return __DIR__ . '/../script-docs/azure-devops.md'; }
    public function isIntegration(): bool { return true; }
}
